class Solution {
    private int answer;

    public int totalNQueens(int n) {
        answer = 0;
        boolean[] columns = new boolean[n];
        boolean[] mainDiag = new boolean[2 * n - 1];
        boolean[] antiDiag = new boolean[2 * n - 1];
        place(0, n, columns, mainDiag, antiDiag);
        return answer;
    }

    private void place(int row, int n, boolean[] columns, boolean[] mainDiag, boolean[] antiDiag) {
        if (row == n) {
            answer++;
            return;
        }

        for (int col = 0; col < n; col++) {
            int main = row - col + n - 1;
            int anti = row + col;
            if (columns[col] || mainDiag[main] || antiDiag[anti]) {
                continue;
            }
            columns[col] = true;
            mainDiag[main] = true;
            antiDiag[anti] = true;
            place(row + 1, n, columns, mainDiag, antiDiag);
            columns[col] = false;
            mainDiag[main] = false;
            antiDiag[anti] = false;
        }
    }
}

class Solution {
    private int fullMask;

    public int totalNQueens(int n) {
        fullMask = (1 << n) - 1;
        return count(0, 0, 0);
    }

    private int count(int columns, int diagonals, int antiDiagonals) {
        if (columns == fullMask) {
            return 1;
        }

        int available = fullMask & ~(columns | diagonals | antiDiagonals);
        int total = 0;
        while (available != 0) {
            int bit = available & -available;
            available -= bit;
            total += count(columns | bit, (diagonals | bit) << 1, (antiDiagonals | bit) >>> 1);
        }
        return total;
    }
}

class Solution {
    private int n;
    private int fullMask;

    public int totalNQueens(int n) {
        this.n = n;
        this.fullMask = (1 << n) - 1;
        int total = 0;

        for (int col = 0; col < n / 2; col++) {
            int bit = 1 << col;
            total += 2 * countFromRow(1, bit, bit << 1, bit >>> 1);
        }
        if ((n & 1) == 1) {
            int bit = 1 << (n / 2);
            total += countFromRow(1, bit, bit << 1, bit >>> 1);
        }
        return total;
    }

    private int countFromRow(int row, int columns, int diagonals, int antiDiagonals) {
        if (row == n) {
            return 1;
        }
        int available = fullMask & ~(columns | diagonals | antiDiagonals);
        int total = 0;
        while (available != 0) {
            int bit = available & -available;
            available -= bit;
            total += countFromRow(row + 1, columns | bit, (diagonals | bit) << 1, (antiDiagonals | bit) >>> 1);
        }
        return total;
    }
}

class Solution {
    private int answer;

    public int totalNQueens(int n) {
        answer = 0;
        int[] queenColumn = new int[n];
        boolean[] usedColumns = new boolean[n];
        search(0, n, queenColumn, usedColumns);
        return answer;
    }

    private void search(int row, int n, int[] queenColumn, boolean[] usedColumns) {
        if (row == n) {
            answer++;
            return;
        }

        for (int col = 0; col < n; col++) {
            if (usedColumns[col] || hasDiagonalConflict(row, col, queenColumn)) {
                continue;
            }
            queenColumn[row] = col;
            usedColumns[col] = true;
            search(row + 1, n, queenColumn, usedColumns);
            usedColumns[col] = false;
        }
    }

    private boolean hasDiagonalConflict(int row, int col, int[] queenColumn) {
        for (int prev = 0; prev < row; prev++) {
            if (Math.abs(row - prev) == Math.abs(col - queenColumn[prev])) {
                return true;
            }
        }
        return false;
    }
}
